    'Aspirin': 0,
    'DMSO': 0,
}

records = []
for r in [4, 5, 6, 7, 8, 10, 12, 13, 14, 15, 16, 17]:
    row = rows[r - 1]
    drug = str(row[1]).strip()
    mid_value = str(row[3]).strip()
    prediction = 1 if mid_value.startswith('↑') else 0
    records.append({
        'id': drug,
        'score': {
            'ref': f'article.xml/Table 2./R{r}C4',
            'map': {mid_value: prediction}
        },
        'truth': {
            'ref': f'article.xml/Table 2./R{r}C2',
            'map': {drug: truth_by_drug[drug]}
        }
    })

# Independent executable check of the bound binary records.
scores = [next(iter(x['score']['map'].values())) for x in records]
truths = [next(iter(x['truth']['map'].values())) for x in records]
accuracy = sum(int(s > 0.5) == t for s, t in zip(scores, truths)) / len(records)
assert len(records) == 12
assert abs(accuracy - 11/12) < 1e-12

